const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{mode:'READ_ONLY',result:'BLOCKED',reason:'LEDGER_ERROR_OR_MISSING',canSend:false}}];
const out=a.map(x=>{
 const code=String(x.error_code||'');
 const policy=code==='131050'?'MARKETING_OPT_OUT_HARD_SUPPRESSION_REQUIRED':
 code==='131048'?'QUALITY_RESTRICTION_SUSPEND_AND_REVIEW':
 code==='131049'?'RECIPIENT_MARKETING_HOLD_EXISTING_CRM_POLICY':
 code==='131026'?'UNDELIVERABLE_UNKNOWN_DO_NOT_MARK_UNREGISTERED':
 code==='130472'?'MARKETING_EXPERIMENT_DELAYED_REVIEW':
 code==='132015'?'TEMPLATE_PACING_QUALITY_REVIEW':'UNKNOWN_REQUIRES_REVIEW';
 return {code,count:Number(x.occurrences)||0,latest:x.last_seen,classification:policy};
});
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',result:out.length?'REVIEW':'NO_ERRORS_RECORDED',
 errors:out,marketingOptouts:out.filter(x=>x.code==='131050').reduce((sum,x)=>sum+x.count,0),
 changesMade:0,canSend:false,crmEventWriteAuthorized:false,
 note:'Read-only exceptions; CRM suppression write and provider opt-out sync are NOT yet connected.'}}];
